mapper.sql:
AND n.deleted = 0

    AND n.category_id = #{query.categoryId}


    AND n.status = #{query.status}


    AND n.title LIKE CONCAT('%', #{query.keyword}, '%')


    AND EXISTS (
        SELECT 1
        FROM note_note_tag nt2
        WHERE nt2.note_id = n.id
          AND nt2.tag_id IN

              #{tid}

    )

mapper.select:
SELECT nt.note_id, nt.tag_id, t.name AS tag_name FROM note_note_tag nt JOIN note_tag t ON t.id = nt.tag_id WHERE nt.note_id IN
#{id}
ORDER BY t.name ASC
